type CityAssetSpec = readonly [model: string, label: string, width: number, depth: number, height: number, group: string, collision?: boolean];
const kenneyRoadAssets = (pack: "city-kit-roads" | "city-kit-suburban", specs: readonly CityAssetSpec[]): RoomPropDefinition[] => specs.map(([model, label, width, depth, height, group, collision = false]) => ({
  asset: `kenney-${pack}-${model}`,
  label,
  width,
  depth,
  height,
  collision,
  model,
  pack,
  format: "gltf",
  group,
  modelUrl: `/assets/kenney/${pack}/Models/${model}.glb`,
  preview: `/assets/kenney/${pack}/Previews/${model}.png`,
}));

